'use strict';
const kitchen=id=>document.getElementById(id);
let cookToken=0;
function kitchenOptions(){kitchen('cook-third').innerHTML=(kitchen('cook-exp').value==='B'?['New','Old']:['Butter','Salt']).map(x=>`<option>${x}</option>`).join('');resetKitchen();}
function resetKitchen(){cookToken++;kitchen('cook').disabled=false;kitchen('cook').textContent='Start heating ▶';kitchen('cook-stage').textContent='Choose your settings. Guess first, then press start.';kitchen('cook-result').innerHTML='';kitchen('pop-tray').innerHTML='';document.querySelector('.movie-scene').classList.remove('heating');}
function finishCooking(token){if(token!==cookToken)return;const exp=kitchen('cook-exp').value,time=+kitchen('cook-time').value,power=kitchen('cook-power').value,third=kitchen('cook-third').value;const selected=LAB_DATA[exp].rows.filter(r=>r.time===time&&r.power===power&&r.third===third);const avg=key=>selected.reduce((s,r)=>s+r[key],0)/selected.length;const groups=exp==='B'?[['good','Successful pops',avg('success')],['bad','Failed: unpopped + burnt',avg('failed')]]:[['raw','Unpopped',avg('unpopped')],['burnt','Burnt',avg('burnt')]];kitchen('cook-stage').textContent=`Ding! ${time} s / ${power} / ${third} · ${exp==='B'?'Storage study B':'Flavour study A'}`;kitchen('pop-tray').innerHTML=groups.map(([cls,label])=>`<div class="tray-group"><div>${Array.from({length:12},(_,i)=>`<i class="food ${cls}" style="--turn:${i*47}deg"></i>`).join('')}</div><small>${label}</small></div>`).join('');kitchen('cook-result').innerHTML='<div class="serving-numbers">'+groups.map(([,label,value])=>`<div><strong>${value.toFixed(2)}</strong><span>${label} per bag</span></div>`).join('')+'</div>'+`<p>Across ${selected.length} recorded bags, averaged across blocks. ${exp==='A'?'Successful counts were not recorded; edible yield cannot be inferred.':'Failed counts were not split into unpopped and burnt; their separate shares are unknown.'}</p>`;kitchen('cook').disabled=false;kitchen('cook').textContent='Try another setting ↻';document.querySelector('.movie-scene').classList.remove('heating');}
kitchen('cook').onclick=()=>{const token=++cookToken;kitchen('cook').disabled=true;kitchen('cook-stage').textContent='Heating… a fast-forward illustration. Recorded bag averages appear at the end.';document.querySelector('.movie-scene').classList.add('heating');const seconds=+kitchen('cook-time').value;kitchen('scene-timer').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');kitchen('scene-power').textContent=kitchen('cook-power').value.toUpperCase();if(matchMedia('(prefers-reduced-motion: reduce)').matches)finishCooking(token);else setTimeout(()=>finishCooking(token),1400);};
kitchen('cook-exp').onchange=kitchenOptions;['cook-time','cook-power','cook-third'].forEach(id=>kitchen(id).onchange=resetKitchen);
document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{const q=b.dataset.question;kitchen('cook-exp').value=q==='flavour'?'A':'B';kitchenOptions();changeExperiment(kitchen('cook-exp').value);kitchen('kitchen').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});
kitchenOptions();changeExperiment('B');
